                                <div className="flex items-center gap-3">
                                    <input 
                                        type="range" 
                                        min="1.0" 
                                        max="4.0" 
                                        step="0.1" 
                                        value={settings.lineBrighteningWidth || 1.0} 
                                        onChange={(e) => handleChange('lineBrighteningWidth', parseFloat(e.target.value))} 
